export const mapStructures=id=>STRUCTURES.filter(s=>s.mapId===id);
export function structureCell(g,x,y){return !!g.structureMask?.[Math.round(y)*g.width+Math.round(x)]}
export const movementEdgeKey=(a,b)=>{const x=a.x+','+a.y,y=b.x+','+b.y;return x<y?x+'|'+y:y+'|'+x};
export function exteriorActorDepth(g,a){let depth=a.x+a.y;if(structureCell(g,a.x,a.y))return depth;for(const b of g.structures||[]){if(!b.exteriorDoorOrdering?.enabled)continue;if(b.exteriorDoorOrdering.eligibleOffsets.some(([dx,dy])=>b.x+dx===a.x&&b.y+dy===a.y))depth=Math.max(depth,b.x+b.y+.02)}return depth}
